// SF-043: multi-fleet presentation adapter; combat remains the existing Starfall resolver.
let bcWorkspace=null,bcLegacySignature='',bcCombat=null;
const bcClasses=['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'];
function bcEscape(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function bcInvalidate(){bcCombat=null;window.bcalcResult=null;}
function bcSafeCounts(raw){const out={};for(const [id,n] of Object.entries(raw||{})){if(!SHIPS[id])continue;const value=Number(n);if(!Number.isSafeInteger(value)||value<0||value>1000000000)throw Error('Ship counts must be whole numbers between 0 and 1,000,000,000.');if(value)out[id]=value;}return out;}
function bcAggregate(fleets){const result={};for(const fleet of fleets){for(const [id,n] of Object.entries(bcSafeCounts(fleet))){result[id]=(result[id]||0)+n;if(result[id]>1000000000)throw Error('Combined ship counts exceed 1,000,000,000.');}}return result;}
function bcSignature(legacy){return JSON.stringify({a:legacy?.a||{},d:legacy?.d||{},population:legacy?.population??1000,biodomes:legacy?.biodomes??0,biodomeDamage:legacy?.biodomeDamage??0});}
function bcEnsureWorkspace(){const legacy=window.bcalc||{a:{},d:{}};const signature=bcSignature(legacy);if(!bcWorkspace||signature!==bcLegacySignature){bcWorkspace={a:[bcSafeCounts(legacy.a)],d:[bcSafeCounts(legacy.d)],filters:{a:{classes:[...bcClasses],race:''},d:{classes:[...bcClasses],race:''}},population:legacy.population??1000,biodomes:legacy.biodomes??0,biodomeDamage:legacy.biodomeDamage??0,title:'Calculator engagement',scan:'',targetFleet:'d:0',metadata:{a:{coords:'',value:'',score:''},d:{coords:'',value:'',score:''}}};bcCombat=null;bcLegacySignature=signature;}return bcWorkspace;}
function bcPublish(){window.bcalc={a:bcAggregate(bcWorkspace.a),d:bcAggregate(bcWorkspace.d),population:bcWorkspace.population,biodomes:bcWorkspace.biodomes,biodomeDamage:bcWorkspace.biodomeDamage};bcLegacySignature=bcSignature(window.bcalc);}
function bcChangeFleet(side,action,index){if(!['a','d'].includes(side))throw Error('Unknown battle side.');bcEnsureWorkspace();const fleets=bcWorkspace[side];if(action==='add'){if(fleets.length>=4)throw Error('A maximum of four fleets per side.');fleets.push({});}else if(action==='remove'){if(fleets.length===1)throw Error('Keep at least one fleet.');if(!Number.isInteger(index)||!fleets[index])throw Error('Choose an existing fleet.');fleets.splice(index,1);}else if(action==='reset'){if(!fleets[index])throw Error('Choose an existing fleet.');fleets[index]={};}else throw Error('Unknown fleet action.');bcInvalidate();bcPublish();}
function bcSetCount(side,index,id,value){bcEnsureWorkspace();if(!bcWorkspace[side]?.[index]||!SHIPS[id])throw Error('Choose an existing fleet and ship.');const before=bcWorkspace[side][index][id];const safe=bcSafeCounts({[id]:value});bcWorkspace[side][index][id]=safe[id]||0;try{bcAggregate(bcWorkspace[side]);}catch(e){if(before===undefined)delete bcWorkspace[side][index][id];else bcWorkspace[side][index][id]=before;throw e;}bcInvalidate();bcPublish();}
function bcImportCounts(side,index,counts){bcEnsureWorkspace();if(!bcWorkspace[side]?.[index])throw Error('Choose an existing target fleet.');const next={...bcWorkspace[side][index]};for(const [id,n] of Object.entries(bcSafeCounts(counts)))next[id]=(next[id]||0)+n;const all=bcWorkspace[side].map((f,i)=>i===index?next:f);bcAggregate(all);bcWorkspace[side][index]=next;bcInvalidate();bcPublish();}
function bcSwapSides(){bcEnsureWorkspace();[bcWorkspace.a,bcWorkspace.d]=[bcWorkspace.d,bcWorkspace.a];[bcWorkspace.metadata.a,bcWorkspace.metadata.d]=[bcWorkspace.metadata.d,bcWorkspace.metadata.a];[bcWorkspace.filters.a,bcWorkspace.filters.d]=[bcWorkspace.filters.d,bcWorkspace.filters.a];bcInvalidate();bcPublish();}
function bcSaveDraft(){bcEnsureWorkspace();localStorage.setItem('starfall-battle-draft-v1',JSON.stringify(bcWorkspace));}
function bcLoadDraft(){const saved=JSON.parse(localStorage.getItem('starfall-battle-draft-v1')||'null');if(!saved)throw Error('No saved calculator draft.');for(const side of ['a','d']){if(!Array.isArray(saved[side])||saved[side].length<1||saved[side].length>4)throw Error('Saved draft has invalid fleets.');saved[side]=saved[side].map(bcSafeCounts);bcAggregate(saved[side]);}for(const [key,max] of [['population',1000000000],['biodomes',1000000000],['biodomeDamage',999]])if(!Number.isSafeInteger(Number(saved[key]))||Number(saved[key])<0||Number(saved[key])>max)throw Error('Saved habitat values are invalid.');const old=bcEnsureWorkspace();bcWorkspace={...old,...saved,filters:old.filters,metadata:saved.metadata||old.metadata};bcInvalidate();bcPublish();}
function bcVisibleShips(side){const filter=bcEnsureWorkspace().filters[side];return Object.entries(SHIPS).filter(([,ship])=>(!filter.race||ship.race===filter.race)&&(!bcClasses.includes(ship.class)||filter.classes.includes(ship.class)));}
function bcSideHTML(side){const w=bcWorkspace,fleets=w[side],total=bcAggregate(fleets),survivors=bcCombat?.[side==='a'?'attacker':'defender']||{},races=[...new Set(Object.values(SHIPS).map(s=>s.race))],meta=w.metadata[side];return '<section class="panel bc43-side"><div class="ph"><div class="pt">'+(side==='d'?'DEFENCE':'ATTACK')+'</div><span>'+fleets.length+' / 4 FLEETS</span></div><div class="bc43-body"><div class="bc43-filters"><label>Race display<select data-bc-race="'+side+'"><option value="">All races</option>'+races.map(r=>'<option '+(w.filters[side].race===r?'selected':'')+'>'+bcEscape(r)+'</option>').join('')+'</select></label><div>'+bcClasses.map((c,i)=>'<label><input type="checkbox" data-bc-class="'+side+'" value="'+c+'" '+(w.filters[side].classes.includes(c)?'checked':'')+'>'+['Fi','Co','Fr','De','Cr','Bs'][i]+'</label>').join('')+'</div></div><div class="bc43-metadata">'+['coords','value','score'].map(k=>'<label>'+k+'<input data-bc-meta="'+side+'" data-key="'+k+'" value="'+bcEscape(meta[k])+'"></label>').join('')+'</div><p class="bc43-help">Race filters and metadata are display context. Every fleet, including hidden ship rows, participates in combat.</p><div class="bc43-actions"><button class="btn" data-bc-action="add" data-side="'+side+'" '+(fleets.length===4?'disabled':'')+'>ADD FLEET</button>'+fleets.map((f,i)=>'<span>F'+(i+1)+' <button class="btn" data-bc-action="reset" data-side="'+side+'" data-index="'+i+'">RESET</button><button class="btn" data-bc-action="remove" data-side="'+side+'" data-index="'+i+'" '+(fleets.length===1?'disabled':'')+'>REMOVE</button></span>').join('')+'</div><div class="table-wrap"><table><thead><tr><th>Ship</th>'+fleets.map((f,i)=>'<th>F'+(i+1)+'</th>').join('')+'<th>Total</th><th>Killed</th><th>EMPed</th><th>Stolen</th></tr></thead><tbody>'+bcVisibleShips(side).map(([id,ship])=>'<tr><th>'+bcEscape(ship.name)+'<small>'+bcEscape(ship.race)+' · '+bcEscape(ship.class)+'</small></th>'+fleets.map((f,i)=>'<td><input type="number" min="0" max="1000000000" step="1" aria-label="'+bcEscape(ship.name)+' '+(side==='a'?'attack':'defence')+' fleet '+(i+1)+'" data-bc-count="'+side+'" data-index="'+i+'" data-ship="'+bcEscape(id)+'" value="'+(f[id]||0)+'"></td>').join('')+'<td>'+nfmt(total[id]||0)+'</td><td>'+(bcCombat?nfmt((total[id]||0)-(survivors[id]||0)):'—')+'</td><td>—</td><td>—</td></tr>').join('')+'</tbody></table></div><p>Combined ships: <b>'+nfmt(Object.values(total).reduce((n,v)=>n+v,0))+'</b>. Killed counts combine all fleets; EMP and theft are not supplied by this resolver.</p></div></section>';}
function bc43HTML(){try{const w=bcEnsureWorkspace();return '<div class="bc43"><div class="bc43-toolbar"><input aria-label="Battle title" id="calcTitle" data-bc-setting="title" value="'+bcEscape(w.title)+'"><button class="btn" data-bc-command="save">SAVE DRAFT</button><button class="btn" data-bc-command="load">LOAD DRAFT</button><button class="btn" data-bc-command="swap">SWITCH SIDES</button><button class="btn" data-bc-command="update">UPDATE</button><button class="btn primary" data-calculate>CALCULATE</button><button class="btn" data-copycalc="report">COPY INPUT</button></div><div class="bc43-columns">'+bcSideHTML('d')+bcSideHTML('a')+'</div><section class="panel"><div class="ph"><div class="pt">DEFENDER HABITAT & SCAN IMPORT</div></div><div class="bc43-body"><div class="bc43-metadata">'+[['population','calcPopulation',1000000000],['biodomes','calcBiodomes',1000000000],['biodomeDamage','calcBiodomeDamage',999]].map(([key,id,max])=>'<label>'+key+'<input type="number" min="0" max="'+max+'" step="1" id="'+id+'" data-bc-setting="'+key+'" value="'+bcEscape(w[key])+'"></label>').join('')+'</div><textarea id="bcSharedReport" aria-label="Paste scan or ship report" placeholder="Paste a ship report to add counts to the selected fleet">'+bcEscape(w.scan)+'</textarea><div class="bc43-actions"><select id="bcTargetFleet" aria-label="Scan target fleet">'+['d','a'].map(side=>w[side].map((f,i)=>'<option value="'+side+':'+i+'" '+(w.targetFleet===side+':'+i?'selected':'')+'>'+(side==='d'?'Defence':'Attack')+' F'+(i+1)+'</option>').join('')).join('')+'</select><button class="btn" data-bc-command="parse">ADD REPORT TO FLEET</button></div><div class="scanlink-import"><label for="scanLinkInput">Shared Starfall scan link</label><textarea id="scanLinkInput"></textarea><select id="scanImportSide"><option value="d">Defence</option><option value="a">Attack</option></select><button class="btn" data-bc-command="legacyImport">IMPORT REPORT</button></div><p>Population and Biodomes use the existing combat rules. Asteroid/resource capture, MC, War and EMP are not calculated by this fleet preview.</p></div></section><section class="panel"><div class="ph"><div class="pt">AGGREGATED COMBAT RESULT</div></div><div class="bc43-body">'+(window.bcalcResult||'<p>Calculate to inspect losses and surviving ships.</p>')+'</div></section></div>';}catch(error){return '<div class="note">'+bcEscape(error.message)+'</div>';}}
function bc43Calculate(){try{const w=bcEnsureWorkspace(),a=bcAggregate(w.a),d=bcAggregate(w.d);for(const [key,max] of [['population',1000000000],['biodomes',1000000000],['biodomeDamage',999]])if(!Number.isSafeInteger(Number(w[key]))||Number(w[key])<0||Number(w[key])>max)throw Error('Use valid whole population and habitat values.');const x=resolveCombat(a,d,undefined,undefined,Number(w.population),Number(w.biodomes),Number(w.biodomeDamage));bcCombat=x;bcPublish();window.bcalcResult='<b>COMBINED FLEET RESULT</b><p>Attack lost '+nfmt(x.aLost)+' · Defence lost '+nfmt(x.dLost)+'</p><p>Surviving attack '+nfmt(totalShips(x.attacker))+' · Surviving defence '+nfmt(totalShips(x.defender))+'</p>';if(typeof recordSimulatedCalculatorReport==='function'){const report=recordSimulatedCalculatorReport(x,w.title||'Calculator engagement');window.bcalcResult+=battleNewsHTML(report);}renderAlliance();}catch(error){notify(error.message,true);}}
if(typeof bcalcHTML==='function')bcalcHTML=bc43HTML;
if(typeof calculateBattle==='function')calculateBattle=bc43Calculate;
function bc43Copy(kind){bcEnsureWorkspace();const lines=side=>Object.entries(bcAggregate(bcWorkspace[side])).map(([id,n])=>SHIPS[id].name+': '+n).join('\n')||'No ships';return kind==='attacker'?lines('a'):kind==='defender'?lines('d'):kind==='report'?'ATTACKER\n'+lines('a')+'\n\nDEFENDER\n'+lines('d'):String(window.bcalcResult||'No calculated result.').replace(/<[^>]*>/g,' ');}
if(typeof bcalcCopy==='function')bcalcCopy=bc43Copy;
document.addEventListener('change',event=>{const el=event.target;try{if(el.id==='bcTargetFleet'){bcEnsureWorkspace().targetFleet=el.value;}else if(el.dataset.bcCount){bcSetCount(el.dataset.bcCount,Number(el.dataset.index),el.dataset.ship,el.value);renderAlliance();}else if(el.dataset.bcSetting){bcEnsureWorkspace()[el.dataset.bcSetting]=el.dataset.bcSetting==='title'?el.value:Number(el.value);bcInvalidate();bcPublish();}else if(el.dataset.bcMeta){bcEnsureWorkspace().metadata[el.dataset.bcMeta][el.dataset.key]=el.value;}else if(el.dataset.bcRace){bcEnsureWorkspace().filters[el.dataset.bcRace].race=el.value;renderAlliance();}else if(el.dataset.bcClass){const f=bcEnsureWorkspace().filters[el.dataset.bcClass];f.classes=el.checked?[...new Set([...f.classes,el.value])]:f.classes.filter(c=>c!==el.value);renderAlliance();}}catch(error){notify(error.message,true);}});
document.addEventListener('input',event=>{if(event.target.id==='bcSharedReport')bcEnsureWorkspace().scan=event.target.value;});
document.addEventListener('click',event=>{const el=event.target.closest('[data-bc-action],[data-bc-command]');if(!el||el.disabled)return;try{if(el.dataset.bcAction)bcChangeFleet(el.dataset.side,el.dataset.bcAction,Number(el.dataset.index));else{const action=el.dataset.bcCommand;if(action==='save'){bcSaveDraft();notify('Calculator draft saved in this browser.');}if(action==='load')bcLoadDraft();if(action==='swap')bcSwapSides();if(action==='legacyImport'){const text=document.getElementById('scanLinkInput').value,side=document.getElementById('scanImportSide').value;const counts=parseShipReport(text);if(!Object.values(counts).some(n=>n>0))throw Error('Paste the shared scan report text; a URL alone does not contain ship counts.');bcImportCounts(side,0,counts);}if(action==='parse'){const [side,index]=document.getElementById('bcTargetFleet').value.split(':');bcImportCounts(side,Number(index),parseShipReport(bcEnsureWorkspace().scan));}}renderAlliance();}catch(error){notify(error.message,true);}});

